//! Static contract for *creating* a transition. Sibling to
//! `E2ETransition` (which is generated by `declare_transitions!` and
//! holds the instance methods).
//!
//! Lives outside the macro because static methods can't be enum-
//! dispatched — there's no self to match on. Each variant impls this
//! directly; the strategy aggregator calls it per-type.

use crate::reference::RefState;
use proptest::strategy::BoxedStrategy;

pub trait E2ETransitionFactory: Sized {
    /// If this transition kind applies in `state`, return its
    /// `(weight, generator)` for the prop_oneof aggregator. `None`
    /// removes it from this step entirely (no wasted strategy
    /// construction, no zero-weight bookkeeping).
    fn weighted_generator(state: &RefState) -> Option<(u32, BoxedStrategy<Self>)>;
}
